import csv,json,html,hashlib,sys
from collections import Counter
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
L=ROOT/'.local/r8-quality-20261109-v1';D=ROOT/'docs/r8-quality-20261109-v1';O=ROOT/'.local/r7-20261106-v1'
def read(p):return json.loads(Path(p).read_text('utf8'))
def write(name,x):
 p=D/name;p.parent.mkdir(exist_ok=True,parents=True);p.write_text(x if isinstance(x,str) else json.dumps(x,ensure_ascii=False,indent=2),'utf8')
def table(head,rows):return '| '+' | '.join(head)+' |\n|'+'|'.join(['---']*len(head))+'|\n'+'\n'.join('| '+' | '.join(str(x).replace('|','/') for x in r)+' |' for r in rows)
ROOTS={4:['REAL_REPLY_DEFECT'],6:['UNDETERMINED'],9:['UNVERIFIED_POLICY'],11:['REAL_REPLY_DEFECT'],13:['GUARD_FALSE_BLOCK'],14:['UNVERIFIED_POLICY'],15:['ANALYSIS_OR_ATTRIBUTION_ERROR','PLANNER_OR_TOOL_ERROR','REAL_REPLY_DEFECT'],16:['UNVERIFIED_POLICY'],17:['GUARD_FALSE_BLOCK','REAL_REPLY_DEFECT'],18:['REAL_REPLY_DEFECT'],19:['REAL_REPLY_DEFECT'],21:['REAL_REPLY_DEFECT'],30:['GUARD_FALSE_BLOCK','REAL_REPLY_DEFECT'],31:['GUARD_FALSE_BLOCK'],37:['REAL_REPLY_DEFECT'],38:['GUARD_FALSE_BLOCK','REAL_REPLY_DEFECT'],42:['ANALYSIS_OR_ATTRIBUTION_ERROR'],43:['GUARD_FALSE_BLOCK'],45:['GUARD_FALSE_BLOCK','REAL_REPLY_DEFECT'],49:['GUARD_FALSE_BLOCK','JUDGE_ERROR'],51:['REAL_REPLY_DEFECT','ANALYSIS_OR_ATTRIBUTION_ERROR']}
