 cases=read(L/'cases.json');records=[];book=['# R8 全部54封已曝光DEV案例册\n\n原R7结论逐字保留。新审阅为Codex AI辅助，非真人Gold；未形成独立人工结论。所有任务为本地模拟。\n']
 for c in cases:
  r=read(c['record_path']);cid=c['case_id'];i=int(cid[-3:]);analysis=r['analysis'];old=c['old'];jp=O/'judgments'/('HOLDOUTPAIR-'+cid+'.json');j=read(jp) if jp.exists() else None
  audit=audit_slot(r['slot'],EmailInput.model_validate(r['email']))
  entry=dict(case_id=cid,input_hash=r['slot']['input_hash'],run_id=r['slot']['run_id'],arm='GUIDED',response_version=r['composer']['version'],old_verdict=old['ai_full_chain'],old_reason=old['reason'],root_categories=ROOTS.get(i,['NO_IDENTIFIED_DEFECT_AI_PROVISIONAL']),replay_guard=audit,judge=j,record_path=c['record_path'])
  records.append(entry)
